        new() {DC = "7110", R1 = null, R2 = "WHEN SURGERY IS REQUIRED, A 100-PERCENT RATING BEGINS ON THE DATE A PHYSICIAN RECOMMENDS SURGICAL CORRECTION WITH A MANDATORY VA EXAMINATION SIX MONTHS FOLLOWING HOSPITAL DISCHARGE. EVALUATE POST-SURGICAL LEFTOVER SYMPTOMS UNDER THE GENERAL RATING FORMULA. ANY CHANGE IN RATING BASED UPON THAT OR ANY SUBSEQUENT EXAMINATION SHALL BE SUBJECT TO THE PROVISIONS OF § 3.105(E) OF THIS CHAPTER.", R3 = null, R4 = null, R5 = null, R6 = null, R7 = null, R8 = null },
